struct Writer<'a, S: crate::cache_storage::Storage> {
    job: &'a mut S,
    cache: JobDashCache,
    steps: usize,
    capacity: crate::cache_capacity::CacheCapacity,
}
impl<S: crate::cache_storage::Storage> Writer<'_, S> {
    fn ensure<T: vexel_scene::JobElement>(
        budget: &mut crate::cache_capacity::CacheCapacity,
        job: &mut S,
        handle: vexel_scene::JobBuffer<T>,
        needed: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let current = job.capacity(handle)?;
        if needed <= current {
            return Ok(());
        }
        let mut capacity = if current == 0 { 32 } else { current };
        while capacity < needed {
            capacity = capacity
                .checked_add((capacity / 8).max(1))
                .ok_or_else(dash_limit)?;
        }
        budget.reserve(job, handle, capacity, control)
    }
    fn step(&mut self, n: usize, control: &mut dyn WorkControl) -> Result<()> {
        if n > DASH_CACHE_MAX_STEPS.saturating_sub(self.steps) {
            return Err(dash_limit());
        }
        control
            .charge(WorkKind::StrokeTest, n as u64)
            .map_err(stopped)?;
        self.steps += n;
        Ok(())
    }
    fn segment(
        &mut self,
        edge: Edge,
        start_cap: Linecap,
        end_cap: Linecap,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let needed = self
            .job
            .slice(self.cache.segments)?
            .len()
            .checked_add(1)
            .ok_or_else(dash_limit)?;
        Self::ensure(
            &mut self.capacity,
            self.job,
            self.cache.segments,
            needed,
            control,
        )?;
        let segment = DashSegment {
            edge,
            start_cap,
            end_cap,
        };
        self.job.extend(self.cache.segments, &[segment], control)
    }
    fn join(&mut self, a: Edge, b: Edge, control: &mut dyn WorkControl) -> Result<()> {
        let needed = self
            .job
            .slice(self.cache.joins)?
            .len()
            .checked_add(1)
            .ok_or_else(dash_limit)?;
        Self::ensure(
            &mut self.capacity,
            self.job,
            self.cache.joins,
            needed,
            control,
        )?;
        self.job.extend(
            self.cache.joins,
            &[DashJoin {
                previous: a.a,
                vertex: a.b,
                next: b.b,
            }],
            control,
        )
    }
}
fn dashed(
    w: &mut Writer<'_, impl crate::cache_storage::Storage>,
    stroke: &Stroke,
    dashes: &[f64],
    edges: &[Edge],
    first: usize,
    count: usize,
    closed: bool,
    implicit: bool,
    seam: bool,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let mut n = count;
    if !closed && implicit && n > 0 {
        n -= 1;
    }
    if n == 0 {
        return Ok(());
    }
    if dashes.is_empty() || dashes.len() > 16 {
        return Err(dash_limit());
    }
    let exp = dashes
        .len()
        .checked_mul(if dashes.len() % 2 == 1 { 2 } else { 1 })
        .ok_or_else(dash_limit)?;
    w.step(exp, control)?;
    let mut period = 0.0;
    for i in 0..exp {
        let d = dashes[i % dashes.len()];
        if !d.is_finite() || d <= 0.0 || !(period + d).is_finite() {
            return Err(dash_limit());
        }
        period += d;
    }
    if period <= 0.0 {
        return Err(dash_limit());
    }
    let mut phase = stroke.dash_offset % period;
    if !phase.is_finite() {
        return Err(dash_limit());
    }
    if phase < 0.0 {
        phase += period;
    }
    let mut pat = 0usize;
    for _ in 0..=exp {
        if phase < dashes[pat % dashes.len()] {
            break;
        }
        w.step(1, control)?;
        phase -= dashes[pat % dashes.len()];
        pat = (pat + 1) % exp;
    }
    let mut remain = dashes[pat % dashes.len()] - phase;
    if !remain.is_finite() || remain <= 0.0 {
        return Err(dash_limit());
    }
    let mut joins_prev = false;
    for i in 0..n {
        w.step(1, control)?;
        let e = *edges
            .get(first.checked_add(i).ok_or_else(dash_limit)?)
            .ok_or_else(dash_limit)?;
        let dx = e.b.x - e.a.x;
        let dy = e.b.y - e.a.y;
        let len = dx.hypot(dy);
        if !len.is_finite() {
            return Err(dash_limit());
        }
        if len == 0.0 {
            continue;
        }
        let (mut at, mut cont) = (0.0, false);
        while at < len {
            w.step(1, control)?;
            let take = remain.min(len - at);
            let end = at + take;
            if take <= 0.0 || !end.is_finite() {
                return Err(dash_limit());
            }
            let on = pat % 2 == 0;
            let continues = on && end == len && remain - take > 1.0e-12;
            let cross = continues && i + 1 < n;
            if on {
                let a = Point {
                    x: e.a.x + dx * (at / len),
                    y: e.a.y + dy * (at / len),
                };
                let b = Point {
                    x: e.a.x + dx * (end / len),
                    y: e.a.y + dy * (end / len),
                };
                let sc = if at == 0.0 && (joins_prev || (seam && i == 0)) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                let ec = if cross || (end == len && seam && i + 1 == n) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                w.segment(Edge { a, b }, sc, ec, control)?;
            }
            if cross {
                cont = true;
            }
            at = end;
            remain -= take;
            if remain <= 1.0e-12 {
                pat = (pat + 1) % exp;
                remain = dashes[pat % dashes.len()];
            }
        }
        if cont && i + 1 < n {
            w.join(
                e,
                *edges.get(first + i + 1).ok_or_else(dash_limit)?,
                control,
            )?;
        }
        joins_prev = cont;
    }
    if seam {
        w.join(
            *edges.get(first + n - 1).ok_or_else(dash_limit)?,
            *edges.get(first).ok_or_else(dash_limit)?,
            control,
        )?;
